package com.foodshare.dao;
import java.sql.*; import java.util.*; import com.foodshare.database.DBConnection; import com.foodshare.model.DonationPOJO;
public class DonationDAO {
 public boolean addDonation(DonationPOJO d){String q="INSERT INTO donations(title,category,portions,donor_name,donor_email,pickup_address,expiry_hours,dietary,status) VALUES(?,?,?,?,?,?,?,?, 'available')";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,d.getTitle());p.setString(2,d.getCategory());p.setInt(3,d.getPortions());p.setString(4,d.getDonorName());p.setString(5,d.getDonorEmail());p.setString(6,d.getPickupAddress());p.setInt(7,d.getExpiryHours());p.setString(8,d.getDietary());return p.executeUpdate()==1;}catch(SQLException e){System.err.println("[DonationDAO] Insert failed: "+e.getMessage());return false;}}
 public List<DonationPOJO> getAvailableDonations(){List<DonationPOJO> out=new ArrayList<>();String q="SELECT id,title,category,portions,donor_name,donor_email,pickup_address,expiry_hours,dietary,status,claimed_by_name FROM donations WHERE status='available' ORDER BY created_at DESC";try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())out.add(map(r));}catch(SQLException e){System.err.println("[DonationDAO] Load available failed: "+e.getMessage());}return out;}
 public boolean claimDonation(int id,String ngoEmail,String ngoName){String q="UPDATE donations SET status='claimed',claimed_by=?,claimed_by_name=?,claimed_at=NOW() WHERE id=? AND status='available'";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,ngoEmail);p.setString(2,ngoName);p.setInt(3,id);return p.executeUpdate()==1;}catch(SQLException e){System.err.println("[DonationDAO] Claim failed: "+e.getMessage());return false;}}
 public List<DonationPOJO> getClaimsForNgo(String email){List<DonationPOJO> out=new ArrayList<>();String q="SELECT id,title,category,portions,donor_name,donor_email,pickup_address,expiry_hours,dietary,status,claimed_by_name FROM donations WHERE lower(claimed_by)=lower(?) ORDER BY claimed_at DESC";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,email);try(ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}}catch(SQLException e){System.err.println("[DonationDAO] Claims load failed: "+e.getMessage());}return out;}
 public int[] getImpactStats(){String q="SELECT COUNT(*) FILTER (WHERE status='available') active,COALESCE(SUM(portions),0) meals FROM donations";try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){if(r.next()){int meals=r.getInt("meals");return new int[]{r.getInt("active"),meals,(int)Math.round(meals*0.45)};}}catch(SQLException e){System.err.println("[DonationDAO] Stats failed: "+e.getMessage());}return new int[]{0,0,0};}
 private DonationPOJO map(ResultSet r)throws SQLException{DonationPOJO d=new DonationPOJO();d.setId(r.getInt("id"));d.setTitle(r.getString("title"));d.setCategory(r.getString("category"));d.setPortions(r.getInt("portions"));d.setDonorName(r.getString("donor_name"));d.setDonorEmail(r.getString("donor_email"));d.setPickupAddress(r.getString("pickup_address"));d.setExpiryHours(r.getInt("expiry_hours"));d.setDietary(r.getString("dietary"));d.setStatus(r.getString("status"));d.setClaimedBy(r.getString("claimed_by_name"));return d;}
}
